import { characters, scenes, playlists, ENDINGS } from "./script.js";

// ------------------------------------------------------------
//  Element references
// ------------------------------------------------------------
const game        = document.getElementById("game");
const bgA         = document.getElementById("bg-a");
const bgB         = document.getElementById("bg-b");
const stage       = document.getElementById("stage");
const dialogueUI  = document.getElementById("dialogue-ui");
const namePlate   = document.getElementById("name-plate");
const nameText    = document.getElementById("name-text");
const dialogueText= document.getElementById("dialogue-text");
const advanceInd  = document.getElementById("advance-indicator");
const titleCard   = document.getElementById("title-card");
const titleLine1  = document.getElementById("title-card-line1");
const titleLine2  = document.getElementById("title-card-line2");
const choiceUI    = document.getElementById("choice-ui");
const startScreen = document.getElementById("start-screen");
const startEndings= document.getElementById("start-endings");
const galleryCards= document.getElementById("gallery-cards");
const muteBtn     = document.getElementById("mute-btn");

const hud         = document.getElementById("hud");
const clockTime   = document.getElementById("clock-time");
const sweetFill   = document.querySelector("#meter-sweet .meter-fill");
const gritFill    = document.querySelector("#meter-grit .meter-fill");
const toastLayer  = document.getElementById("toast-layer");

const saveMenuBtn   = document.getElementById("save-menu-btn");
const saveMenu      = document.getElementById("save-menu");
const saveSlotsContainer = document.getElementById("save-slots");
const saveCloseBtn  = document.getElementById("save-close");
const saveTabs      = document.querySelectorAll(".save-tab");

// ------------------------------------------------------------
//  Game State
// ------------------------------------------------------------
const ROUTE = "night";
const METER_MAX = 12; // bar fills; endings gate on the raw value

let currentSceneIndex = 0;   // index in the playlist
let currentCommandIndex = 0; // index in the scene array
let isGameActive = false;
let currentSaveMode = "save";

// Story-wide state, persisted in saves.
let sweet = 0;
let grit = 0;
let toppingName = null;   // the combination the player names in Act 1
let beat = 0;            // running beat counter, drives the clock

const AUTOSAVE_KEY = "midnight_autosave";
const ENDINGS_KEY  = "midnight_endings_unlocked";

// ------------------------------------------------------------
//  Clock — SCRIPT-ANCHORED.
//  The script drops explicit { clock: "11:45 PM" } markers at every
//  beat whose text names a time. clockAnchorMins holds that exact
//  time. Between anchors the clock drifts forward slightly with the
//  beat counter, but the drift is capped so it can never reach the
//  next anchor, contradict the on-screen text, or run backwards.
//
//  Minutes are stored on a continuous night timeline where 11:45 PM
//  is minute 0 and times after midnight keep counting up (12:00 AM =
//  15, 6:12 AM = 387) so comparisons never wrap.
// ------------------------------------------------------------
const CLOCK_ORIGIN = 23 * 60 + 45; // 11:45 PM, minute 0 of the night
const EASE_BEATS = 14;             // beats to ease from one anchor toward the next
const EASE_MARGIN = 2;             // stay this many minutes short of the next time

let clockAnchorMins = 0;           // night-minutes of the last { clock } marker
let clockTargetMins = 0;           // the next stated time to ease toward (or =anchor)
let clockAnchorBeat = 0;           // beat count when the marker fired
let clockDisplayMins = 0;          // last shown value (monotonic guard)

// Parse "11:45 PM" / "12:00 AM" / "6:12 AM" into night-minutes from 11:45 PM.
function parseClock(str) {
    const m = /^(\d{1,2}):(\d{2})\s*(AM|PM)$/i.exec(String(str).trim());
    if (!m) return null;
    let h = parseInt(m[1], 10) % 12;
    const min = parseInt(m[2], 10);
    if (/PM/i.test(m[3])) h += 12;         // 11 PM -> 23
    let abs = h * 60 + min;                 // absolute minutes in a 24h day
    let night = abs - CLOCK_ORIGIN;         // relative to 11:45 PM
    if (night < 0) night += 24 * 60;        // after-midnight times wrap forward
    return night;
}

function formatClock(nightMins) {
    let abs = (CLOCK_ORIGIN + Math.round(nightMins)) % (24 * 60);
    let h = Math.floor(abs / 60);
    const mm = String(abs % 60).padStart(2, "0");
    // Night runs 11 PM (hour 23) then 0..6 AM. Only hour 23 is PM.
    const suffix = (h === 23) ? "PM" : "AM";
    let displayH = h % 12;
    if (displayH === 0) displayH = 12;
    return `${displayH}:${mm} ${suffix}`;
}

// { clock: "12:00 AM", until: "2:00 AM" }
//   - pins the clock to the stated time exactly, right now
//   - if `until` is given, the clock will ease toward (but never reach)
//     that next time over the following beats. It snaps precisely again
//     at the next { clock } marker, so text is never contradicted.
function setClockAnchor(str, until) {
    const mins = parseClock(str);
    if (mins == null) return;
    clockAnchorMins = mins;
    const target = until != null ? parseClock(until) : null;
    // Ease toward just short of the next stated time; never below the anchor.
    clockTargetMins = (target != null && target > mins)
        ? target - EASE_MARGIN
        : mins;
    if (clockTargetMins < mins) clockTargetMins = mins;
    clockAnchorBeat = beat;
    clockDisplayMins = mins;
    clockTime.textContent = formatClock(mins);
}

// Reset clock state to the top of the night (11:45 PM, no drift yet).
function resetClock() {
    clockAnchorMins = 0;
    clockTargetMins = 0;
    clockAnchorBeat = beat;
    clockDisplayMins = 0;
    clockTime.textContent = formatClock(0);
}

function updateClock() {
    // Ease from the anchor toward the next stated time as beats accumulate,
    // clamped so it never passes the target, never contradicts text, and
    // never runs backwards.
    const beatsSince = Math.max(0, beat - clockAnchorBeat);
    const t = Math.min(1, beatsSince / EASE_BEATS);
    let mins = clockAnchorMins + (clockTargetMins - clockAnchorMins) * t;
    if (mins < clockDisplayMins) mins = clockDisplayMins;
    clockDisplayMins = mins;
    clockTime.textContent = formatClock(mins);
}

// ------------------------------------------------------------
//  Meters + toasts
// ------------------------------------------------------------
function updateMeters() {
    sweetFill.style.width = `${Math.min(100, (sweet / METER_MAX) * 100)}%`;
    gritFill.style.width  = `${Math.min(100, (grit / METER_MAX) * 100)}%`;
}

function showToast(label, amount) {
    const toast = document.createElement("div");
    toast.className = `meter-toast ${label.toLowerCase()}`;
    toast.textContent = `+${amount} ${label}`;
    toastLayer.appendChild(toast);
    playToastSfx();
    setTimeout(() => toast.classList.add("show"), 20);
    setTimeout(() => {
        toast.classList.remove("show");
        setTimeout(() => toast.remove(), 500);
    }, 1400);
}

function applyMeter(deltaSweet = 0, deltaGrit = 0) {
    if (deltaSweet) { sweet += deltaSweet; showToast("SWEET", deltaSweet); }
    if (deltaGrit)  { grit  += deltaGrit;  setTimeout(() => showToast("GRIT", deltaGrit), deltaSweet ? 260 : 0); }
    updateMeters();
}

// ------------------------------------------------------------
//  Save / Load
// ------------------------------------------------------------
function collectState() {
    return {
        sceneIndex: currentSceneIndex,
        commandIndex: currentCommandIndex,
        sweet, grit, toppingName, beat,
        date: new Date().toLocaleString(),
        summary: `${scenes[playlists[ROUTE][currentSceneIndex]]?.act || "The Night"} — ${clockTime.textContent}`,
    };
}

function saveGame(slotIndex) {
    if (!isGameActive) return;
    localStorage.setItem(`midnight_save_slot_${slotIndex}`, JSON.stringify(collectState()));
    renderSaveSlots();
    refreshContinueButton();
}

function autosave() {
    if (!isGameActive) return;
    localStorage.setItem(AUTOSAVE_KEY, JSON.stringify(collectState()));
    refreshContinueButton();
}

function applyState(data) {
    currentSceneIndex = data.sceneIndex || 0;
    currentCommandIndex = data.commandIndex || 0;
    sweet = data.sweet || 0;
    grit = data.grit || 0;
    toppingName = data.toppingName || null;
    beat = data.beat || 0;
    updateMeters();
    // restoreSceneState() will replay the scene's { clock } markers to pin
    // the correct time; reset first so stale drift never leaks across loads.
    resetClock();
}

async function loadFromData(data) {
    applyState(data);
    saveMenu.classList.add("hidden");
    startScreen.classList.add("hidden");
    startScreen.style.display = "none";
    isGameActive = true;
    hud.classList.remove("hidden");
    hideAllSprites();
    dialogueUI.classList.add("hidden");
    resumeRoute();
}

async function loadGame(slotIndex) {
    const raw = localStorage.getItem(`midnight_save_slot_${slotIndex}`);
    if (!raw) return;
    loadFromData(JSON.parse(raw));
}

function continueGame() {
    const raw = localStorage.getItem(AUTOSAVE_KEY);
    if (!raw) return;
    loadFromData(JSON.parse(raw));
}

function renderSaveSlots() {
    saveSlotsContainer.innerHTML = "";
    for (let i = 1; i <= 6; i++) {
        const raw = localStorage.getItem(`midnight_save_slot_${i}`);
        const slot = document.createElement("div");
        slot.className = "save-slot";
        if (raw) {
            const data = JSON.parse(raw);
            slot.innerHTML = `
                <div class="slot-header">
                    <span>Slot ${i}</span>
                    <span class="slot-date">${data.date}</span>
                </div>
                <div class="slot-info">${data.summary || "Midnight Toppings"}</div>`;
            slot.onclick = () => currentSaveMode === "save" ? saveGame(i) : loadGame(i);
        } else {
            slot.classList.add("empty");
            slot.innerHTML = `Slot ${i} — Empty`;
            if (currentSaveMode === "save") slot.onclick = () => saveGame(i);
        }
        saveSlotsContainer.appendChild(slot);
    }
}

saveMenuBtn.onclick = (e) => {
    e.stopPropagation();
    playClick();
    currentSaveMode = isGameActive ? "save" : "load";
    saveTabs.forEach(t => t.classList.toggle("active", t.dataset.tab === currentSaveMode));
    renderSaveSlots();
    saveMenu.classList.remove("hidden");
};
saveCloseBtn.onclick = (e) => { e.stopPropagation(); playClick(); saveMenu.classList.add("hidden"); };
saveTabs.forEach(tab => {
    tab.onclick = (e) => {
        e.stopPropagation();
        playClick();
        currentSaveMode = tab.dataset.tab;
        saveTabs.forEach(t => t.classList.toggle("active", t === tab));
        renderSaveSlots();
    };
});

// ------------------------------------------------------------
//  Rain overlay
// ------------------------------------------------------------
const rainEl = document.createElement("div");
rainEl.id = "rain";
document.getElementById("bg-layer").appendChild(rainEl);
let rainOffset = 0;

function buildRainTexture() {
    const c = document.createElement("canvas");
    c.width = 256; c.height = 256;
    const ctx = c.getContext("2d");
    ctx.strokeStyle = "rgba(200,180,235,0.5)";
    ctx.lineWidth = 1.2;
    for (let i = 0; i < 70; i++) {
        const x = Math.random() * 256, y = Math.random() * 256;
        const len = 12 + Math.random() * 16;
        ctx.globalAlpha = 0.25 + Math.random() * 0.5;
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x - 3, y + len);
        ctx.stroke();
    }
    rainEl.style.backgroundImage = `url(${c.toDataURL()})`;
    rainEl.style.backgroundSize = "256px 256px";
    animateRain();
}
function animateRain() {
    rainOffset = (rainOffset + 14) % 256;
    rainEl.style.backgroundPosition = `${-rainOffset * 0.3}px ${rainOffset}px`;
    requestAnimationFrame(animateRain);
}
buildRainTexture();

// ------------------------------------------------------------
//  Audio
// ------------------------------------------------------------
const bgm      = new Audio("assets/audio/midnight_theme.mp3");
const sfxClick = new Audio("assets/audio/sfx_click.mp3");
const sfxImpact= new Audio("assets/audio/sfx_impact.mp3");
const sfxToast = new Audio("assets/audio/sfx_toast.mp3");
const sfxUnlock= new Audio("assets/audio/sfx_ending_unlock.mp3");
const sfxTrue  = new Audio("assets/audio/sfx_true_ending.mp3");
bgm.loop = true;
bgm.volume = Math.max(0, Math.min(1, 0.4));
sfxClick.volume = Math.max(0, Math.min(1, 0.5));
sfxImpact.volume = Math.max(0, Math.min(1, 0.55));
sfxToast.volume = Math.max(0, Math.min(1, 0.5));
sfxUnlock.volume = Math.max(0, Math.min(1, 0.65));
sfxTrue.volume = Math.max(0, Math.min(1, 0.75));

let muted = false;
let audioUnlocked = false;
function unlockAudio() {
    if (audioUnlocked) return;
    audioUnlocked = true;
    if (!muted) bgm.play().catch(() => {});
}
function playClick()  { if (!muted) try { sfxClick.currentTime = 0; sfxClick.play().catch(() => {}); } catch (e) {} }
function playImpact() { if (!muted) try { sfxImpact.currentTime = 0; sfxImpact.play().catch(() => {}); } catch (e) {} }
function playToastSfx(){ if (!muted) try { sfxToast.currentTime = 0; sfxToast.play().catch(() => {}); } catch (e) {} }
function playUnlockSfx(){ if (!muted) try { sfxUnlock.currentTime = 0; sfxUnlock.play().catch(() => {}); } catch (e) {} }
function playTrueSfx(){ if (!muted) try { sfxTrue.currentTime = 0; sfxTrue.play().catch(() => {}); } catch (e) {} }

muteBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    muted = !muted;
    muteBtn.classList.toggle("muted", muted);
    muteBtn.textContent = muted ? "✕" : "♪";
    if (muted) { bgm.pause(); sfxTrue.pause(); }
    else if (audioUnlocked) bgm.play().catch(() => {});
});

// ------------------------------------------------------------
//  Background crossfade
// ------------------------------------------------------------
let activeBg = bgA;
let currentBgSrc = null;
const preloadedBgs = new Set();

function preloadBackgrounds() {
    const playlist = playlists[ROUTE];
    playlist.forEach((sceneId) => {
        const scene = scenes[sceneId];
        if (!scene || !scene.beats) return;
        scene.beats.forEach((cmd) => {
            if (cmd.bg && !preloadedBgs.has(cmd.bg)) {
                preloadedBgs.add(cmd.bg);
                const img = new Image();
                img.src = cmd.bg;
            }
        });
    });
}

function setBackground(src) {
    if (src === currentBgSrc) return;
    currentBgSrc = src;
    const incoming = activeBg === bgA ? bgB : bgA;
    const outgoing = activeBg;
    const reveal = () => {
        if (currentBgSrc !== src) return;
        incoming.classList.add("visible");
        outgoing.classList.remove("visible");
    };
    incoming.onload = reveal;
    incoming.onerror = reveal;
    incoming.src = src;
    if (incoming.complete && incoming.naturalWidth > 0) reveal();
    activeBg = incoming;
}

// ------------------------------------------------------------
//  Sprite management
//  One on-stage element PER PERSON, keyed by the base character
//  ("maya", "leo"). Expression variants ("maya_smile") share that
//  element and simply swap its image source, so changing expression
//  never stacks a second sprite for the same person.
// ------------------------------------------------------------
const spriteEls = {};

// The person a character id belongs to, e.g. "maya_smile" -> "maya".
function baseOf(id) {
    if (!id) return id;
    return id.split("_")[0];
}

function ensureSprite(id) {
    const base = baseOf(id);
    if (spriteEls[base]) return spriteEls[base];
    const img = document.createElement("img");
    img.className = "sprite";
    img.alt = "";
    img.src = (characters[id] || characters[base] || {}).sprite || "";
    stage.appendChild(img);
    spriteEls[base] = img;
    return img;
}

// Swap a shown character to a specific expression variant in place.
function setExpression(id) {
    const base = baseOf(id);
    const img = spriteEls[base];
    const src = (characters[id] || characters[base] || {}).sprite;
    if (!img || !src) return;
    if (!img.src.endsWith(src)) img.src = src;
}

function showSprite(id, pos = "center") {
    const img = ensureSprite(id);
    setExpression(id);
    img.classList.remove("pos-center", "pos-left", "pos-right");
    img.classList.add(`pos-${pos}`);
    void img.offsetWidth;
    img.classList.add("visible");
}
function hideSprite(id) { const img = spriteEls[baseOf(id)]; if (img) img.classList.remove("visible"); }
function hideAllSprites() { Object.values(spriteEls).forEach((img) => img.classList.remove("visible")); }

function spriteKeyForSpeaker(id) {
    if (!id || id === "???") return null;
    return baseOf(id);
}
function highlightSpeaker(id) {
    const key = spriteKeyForSpeaker(id);
    Object.entries(spriteEls).forEach(([k, img]) => {
        if (!img.classList.contains("visible")) return;
        img.classList.toggle("dim", key != null && k !== key);
    });
}

// ------------------------------------------------------------
//  Title card
// ------------------------------------------------------------
function showTitleCard(lines) {
    return new Promise((resolve) => {
        titleLine1.textContent = lines[0] || "";
        titleLine2.textContent = lines[1] || "";
        titleLine1.style.animation = "none";
        titleLine2.style.animation = "none";
        void titleLine1.offsetWidth;
        titleLine1.style.animation = "";
        titleLine2.style.animation = "";
        titleCard.classList.remove("hidden");
        const finish = () => {
            game.removeEventListener("pointerdown", clickFinish);
            titleCard.classList.add("hidden");
            setTimeout(resolve, 700);
        };
        const auto = setTimeout(finish, 2800);
        const clickFinish = () => { clearTimeout(auto); finish(); };
        setTimeout(() => game.addEventListener("pointerdown", clickFinish, { once: true }), 500);
    });
}

// ------------------------------------------------------------
//  Typewriter dialogue
// ------------------------------------------------------------
let typing = false;
let skipTyping = false;
let typeResolve = null;

function typeLine(text, isInner) {
    dialogueUI.classList.remove("hidden");
    dialogueText.classList.toggle("inner", !!isInner);
    advanceInd.classList.remove("show");
    dialogueText.textContent = "";
    typing = true;
    skipTyping = false;
    return new Promise((resolve) => {
        typeResolve = resolve;
        let i = 0;
        const speed = 16;
        const tick = () => {
            if (skipTyping) { dialogueText.textContent = text; finishTyping(); return; }
            dialogueText.textContent = text.slice(0, i);
            i++;
            if (i <= text.length) setTimeout(tick, speed);
            else finishTyping();
        };
        tick();
    });
}
function finishTyping() {
    typing = false;
    advanceInd.classList.add("show");
    if (typeResolve) { const r = typeResolve; typeResolve = null; r(); }
}

function showChoices(choices) {
    return new Promise((resolve) => {
        choiceUI.innerHTML = "";
        choiceUI.classList.remove("hidden");
        choices.forEach(c => {
            const btn = document.createElement("button");
            btn.className = "choice-btn";
            btn.textContent = c.text;
            btn.onclick = (e) => {
                e.stopPropagation();
                playClick();
                choiceUI.classList.add("hidden");
                resolve(c);
            };
            choiceUI.appendChild(btn);
        });
    });
}

function waitForAdvance() {
    return new Promise((resolve) => {
        const handler = () => { game.removeEventListener("pointerdown", handler); resolve(); };
        game.addEventListener("pointerdown", handler);
    });
}

// ------------------------------------------------------------
//  Ending router — offers all endings, gates the locked ones.
// ------------------------------------------------------------
// Set when an ending is earned this session so the gallery can pop the
// freshly-lit card once, on the return to the title screen.
let justUnlockedEnding = null;

function unlockEnding(id) {
    let unlocked = [];
    try { unlocked = JSON.parse(localStorage.getItem(ENDINGS_KEY) || "[]"); } catch (e) {}
    const isNew = !unlocked.includes(id);
    if (isNew) {
        unlocked.push(id);
        localStorage.setItem(ENDINGS_KEY, JSON.stringify(unlocked));
    }
    // Always flag it so the gallery celebrates the ending you just reached,
    // even on a repeat clear of a previously-found route.
    justUnlockedEnding = id;
}

function pickEnding() {
    // Choose the best ending the player qualifies for; also list which are met.
    return new Promise((resolve) => {
        choiceUI.innerHTML = "";
        choiceUI.classList.remove("hidden");
        ENDINGS.forEach(ending => {
            const met = ending.gate(sweet, grit);
            const btn = document.createElement("button");
            btn.className = "choice-btn ending-choice" + (met ? "" : " locked");
            btn.innerHTML = met
                ? `<span class="ending-title">${ending.label}</span>`
                : `<span class="ending-title">${ending.label}</span><span class="ending-lock">🔒 ${ending.gateText}</span>`;
            if (met) {
                btn.onclick = (e) => {
                    e.stopPropagation();
                    playClick();
                    choiceUI.classList.add("hidden");
                    resolve(ending.id);
                };
            } else {
                btn.onclick = (e) => { e.stopPropagation(); playClick(); btn.classList.add("shake"); setTimeout(() => btn.classList.remove("shake"), 400); };
            }
            choiceUI.appendChild(btn);
        });
    });
}

// ------------------------------------------------------------
//  Command runner
// ------------------------------------------------------------
function triggerBuzz() {
    game.classList.remove("buzzing");
    void game.offsetWidth;
    game.classList.add("buzzing");
    game.addEventListener("animationend", () => game.classList.remove("buzzing"), { once: true });
}

async function runLine(cmd) {
    if (cmd.bg !== undefined)   setBackground(cmd.bg);
    if (cmd.rain !== undefined) rainEl.classList.toggle("on", !!cmd.rain);
    if (cmd.buzz)               triggerBuzz();
    if (cmd.show)     showSprite(cmd.show, cmd.pos || "center");
    if (cmd.expr)     setExpression(cmd.expr);   // swap expression in place
    if (cmd.hide)     hideSprite(cmd.hide);
    if (cmd.hideAll)  hideAllSprites();
    if (cmd.clock)    setClockAnchor(cmd.clock, cmd.until); // pin clock to script time

    // meter / topping side-effects on plain beats
    if (cmd.sweet || cmd.grit) applyMeter(cmd.sweet || 0, cmd.grit || 0);
    if (cmd.setTopping) toppingName = cmd.setTopping;

    // ending router
    if (cmd.router) {
        const id = await pickEnding();
        unlockEnding(id);
        const ending = ENDINGS.find(e => e.id === id);
        for (const subCmd of ending.beats) await runLine(subCmd);
        return;
    }

    if (cmd.choice) {
        const chosen = await showChoices(cmd.choice);
        if (chosen.sweet || chosen.grit) applyMeter(chosen.sweet || 0, chosen.grit || 0);
        if (chosen.setTopping) toppingName = chosen.setTopping;
        if (chosen.next) for (const subCmd of chosen.next) await runLine(subCmd);
        return;
    }

    if (cmd.title) {
        dialogueUI.classList.add("hidden");
        namePlate.classList.add("hidden");
        await showTitleCard(cmd.title);
        return;
    }

    const hasText = cmd.say !== undefined || cmd.inner !== undefined || cmd.narrate !== undefined;
    if (!hasText) { await wait(160); return; }

    // CLOCK ORDERING: render this beat with the clock exactly as it stands
    // right now. If this beat (or a marker just before it) set an anchor,
    // clockDisplayMins is already pinned to that exact time, so a beat whose
    // text names a time reads that time precisely. Drift toward the next
    // stated time is only applied AFTER the beat renders, when we advance to
    // the next beat — never before. This keeps every anchor exact.

    let text, isInner = false, speakerId = cmd.speaker || null;
    if (cmd.say !== undefined)        { text = resolveTemplate(cmd.say); }
    else if (cmd.inner !== undefined) { text = resolveTemplate(cmd.inner); isInner = true; }
    else                              { text = resolveTemplate(cmd.narrate); speakerId = null; }

    if (speakerId && characters[speakerId]) {
        nameText.textContent = characters[speakerId].name;
        namePlate.classList.remove("hidden");
    } else {
        namePlate.classList.add("hidden");
    }
    highlightSpeaker(speakerId);
    if (cmd.impact) playImpact();

    await typeLine(text, isInner);
    await waitForAdvance();
    playClick();

    // Now that this beat has been read, advance toward the next beat: bump the
    // beat counter and let the clock drift one step closer to the next stated
    // time. The next { clock } marker will re-pin exactly, so text is never
    // contradicted.
    beat++;
    updateClock();
}

// Replace {topping} with the player's named combination (callback motif).
function resolveTemplate(text) {
    if (!text.includes("{topping}")) return text;
    return text.replace(/\{topping\}/g, toppingName || "the Maya Special");
}

function wait(ms) { return new Promise((r) => setTimeout(r, ms)); }

game.addEventListener("pointerdown", () => { if (typing) skipTyping = true; });

// ------------------------------------------------------------
//  Main play loop
// ------------------------------------------------------------
let currentRouteAbortController = null;

function restoreSceneState(beats, upToIndex) {
    for (let i = 0; i < upToIndex && i < beats.length; i++) {
        const cmd = beats[i];
        if (cmd.bg !== undefined)   setBackground(cmd.bg);
        if (cmd.rain !== undefined) rainEl.classList.toggle("on", !!cmd.rain);
        if (cmd.hideAll)            hideAllSprites();
        if (cmd.hide)               hideSprite(cmd.hide);
        if (cmd.show)               showSprite(cmd.show, cmd.pos || "center");
        if (cmd.expr)               setExpression(cmd.expr);
        if (cmd.clock)              setClockAnchor(cmd.clock, cmd.until);
    }
}

async function playScene(sceneId, startFromIndex = 0) {
    const scene = scenes[sceneId];
    if (!scene) return;
    const beats = scene.beats;
    if (startFromIndex > 0) restoreSceneState(beats, startFromIndex);

    for (let i = startFromIndex; i < beats.length; i++) {
        currentCommandIndex = i;
        if (currentRouteAbortController && currentRouteAbortController.signal.aborted) throw new Error("Route aborted");
        await runLine(beats[i]);
        // autosave after every beat
        currentCommandIndex = i + 1;
        autosave();
    }
}

async function playRoute(startFromScene = 0, startFromCommand = 0) {
    if (currentRouteAbortController) currentRouteAbortController.abort();
    currentRouteAbortController = new AbortController();

    isGameActive = true;
    hud.classList.remove("hidden");
    const playlist = playlists[ROUTE];
    preloadBackgrounds();

    try {
        for (let i = startFromScene; i < playlist.length; i++) {
            currentSceneIndex = i;
            const startCmd = (i === startFromScene) ? startFromCommand : 0;
            await playScene(playlist[i], startCmd);
        }
        // End of content -> back to title.
        isGameActive = false;
        localStorage.removeItem(AUTOSAVE_KEY);
        dialogueUI.classList.add("hidden");
        namePlate.classList.add("hidden");
        hud.classList.add("hidden");
        hideAllSprites();
        refreshContinueButton();
        renderUnlockedEndings();
        startScreen.style.display = "flex";
        void startScreen.offsetWidth;
        startScreen.classList.remove("hidden");
    } catch (e) {
        if (e.message === "Route aborted") console.log("Route restarted.");
        else console.error("Game loop error:", e);
    }
}

async function resumeRoute() {
    playRoute(currentSceneIndex, currentCommandIndex);
}

function newGame() {
    currentSceneIndex = 0;
    currentCommandIndex = 0;
    sweet = 0; grit = 0; toppingName = null; beat = 0;
    updateMeters();
    updateClock();
    localStorage.removeItem(AUTOSAVE_KEY);
    startScreen.classList.add("hidden");
    setTimeout(() => { startScreen.style.display = "none"; }, 600);
    hideAllSprites();
    dialogueUI.classList.add("hidden");
    playRoute(0, 0);
}

