            `<span class="glyph-wrap sparkle-${ending.id}">` +
                sparkleField +
                `<span class="card-glyph">${found ? glyph : "❔"}</span>` +
            `</span>` +
            `<span class="card-name">${name}</span>` +
            `<span class="card-status">${status}</span>`;

        card.title = found ? ending.short : `Locked — ${ending.gateText}`;
