    setTimeout(() => toast.classList.add("show"), 20);
    setTimeout(() => {
        toast.classList.remove("show");
        setTimeout(() => toast.remove(), 500);
    }, 1400);
}

function applyMeter(deltaSweet = 0, deltaGrit = 0) {
    if (deltaSweet) { sweet += deltaSweet; showToast("SWEET", deltaSweet); }
    if (deltaGrit)  { grit  += deltaGrit;  setTimeout(() => showToast("GRIT", deltaGrit), deltaSweet ? 260 : 0); }
    updateMeters();
}

